    var nearMax = params.debugMaxPoints || 60
    var nearD = []
    var near = []
    for (var ni = 0; ni < pts.length; ni++) {
      var ddx = pts[ni][0] - pos[0]
      var ddz = pts[ni][1] - pos[2]
