    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  if (state.revCruise && cur.g < 0 && state.segStart !== null) {
    // steady reverse: speed from the free distance along this segment's arc behind the car (stop within it at the comfort deceleration),
    // the lateral acceleration of the arc and the remaining segment length
    var arcLook = Math.min(60, scanRange)
    var freeR = revArcFree(cur, arcLook)
    // the plan itself is collision-free (same costmap) up to its end: a blocked arc beyond this segment is where the plan turns away, not a
    // wall to brake for; only a blockage inside the segment (an obstacle the plan did not know) limits the speed by stopping distance
    var runRemain = remain
    for (var qi = state.idx + 1; qi < state.segs.length && state.segs[qi].g < 0; qi++) runRemain += state.segs[qi].len
    var vRevFree = freeR < Math.min(arcLook, remain) ? Math.sqrt(2 * (params.comfortDecel || 5) * Math.max(0, freeR - 2)) : 1e9
    var vRevCurve = Math.abs(cur.k) > 1e-4 ? Math.sqrt((params.maxLatAccel || 9) / Math.abs(cur.k)) : 1e9
    vMax = Math.min(revCruiseSpeed, vRevFree, vRevCurve, 0.9 + Math.sqrt(2 * 3 * runRemain))
  }
  // waiting for rest before a gear change: demand zero. Once the segment has started but the car still rolls the other
  // way (momentum from the previous segment; an icy car does not stop by itself and a zero-demand brake is below the
  // actuator deadband), drive in the demanded direction: that brakes it hard and turns it around.
  var waitingForRest = state.segStart === null
  var rollingWrong = !waitingForRest && cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: waitingForRest ? 0 : rollingWrong ? cur.g * Math.min(vMax, 2.5) : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

av_motion_planner.code:
// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, horizonClear (m floor, 0 = off), switchMargin (cost; keep last candidate unless better by this, 0 = off), comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, wThreat (0 = off; cost of predicted proximity to av.threats), threatHorizon (s, 2.5), threatRadius (m, 1.8), threatRange (m, 10: proximity felt inside this gap), threatTurnRate (rad/s, 0 = constant-velocity prediction; > 0: bodies faster than threatPursuitSpeed (4 m/s) are predicted HOMING on the car: pure pursuit with that turn-rate limit, threatLead s), threatBodyRadius (m, 0 = off: costmap points within this radius of a fast tracked body are dropped), threatAccel (m/s^2, 0 = constant speed along the candidate), threatHit (x wThreat: penalty of a predicted contact by its time, default 3), threatHitFloor (flat cost of any predicted contact, default 0), marginRamp (m over which the margin grows from the current clearance), debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + margin
  var halfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var aBrake = params.comfortDecel || 5
  // The planning horizon has to cover the stopping distance of the speed we want to drive, otherwise the free-path
  // limit (sqrt(2 * decel * horizon)) silently caps cruiseSpeed (26 m / 5 m/s^2 = 15.8 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var hMax = params.horizonMax != null ? params.horizonMax : Math.min(150, Math.max(26, 1.1 * ((cruiseV * cruiseV) / (2 * aBrake)) + 10))
  var H = Math.min(hMax, hMin + Math.max((params.horizonGain != null ? params.horizonGain : 1.2) * v, (1.1 * v * v) / (2 * aBrake)))
  // horizonClear (m, 0 = off): generous minimum look-ahead independent of the current speed, so a clear road is judged far
  // ahead from a standstill (otherwise slow -> short horizon -> low free-path speed limit stays low). Only a floor: blocked
  // paths still end at the obstacle.
  var hClear = params.horizonClear != null ? params.horizonClear : 0
  if (hClear > H) H = Math.min(hMax, hClear)
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // tracked moving bodies (av.threats from perception) in the ego frame, predicted at constant velocity along every candidate
  var wThreat = params.wThreat != null ? params.wThreat : 0
  var thr = []
  if (wThreat > 0 && av.threats && av.threats.length) {
    for (var tk = 0; tk < av.threats.length; tk++) {
      var tq = av.threats[tk]
      var tdx0 = tq.x - pos[0]
      var tdz0 = tq.z - pos[2]
      if (tdx0 * tdx0 + tdz0 * tdz0 > 90 * 90) continue
      thr.push({
        x: tdx0 * e.fwd[0] + tdz0 * e.fwd[2],
        y: tdx0 * e.left[0] + tdz0 * e.left[2],
        vx: tq.vx * e.fwd[0] + tq.vz * e.fwd[2],
        vy: tq.vx * e.left[0] + tq.vz * e.left[2],
        turn: tq.turn,
      })
      var tl = thr[thr.length - 1]
      tl.sp = Math.sqrt(tl.vx * tl.vx + tl.vy * tl.vy)
      tl.h = Math.atan2(tl.vy, tl.vx)
    }
  }
  var thrH = params.threatHorizon != null ? params.threatHorizon : 2.5
  var thrR = params.threatRadius != null ? params.threatRadius : 1.8
  var thrGap = params.threatRange != null ? params.threatRange : 10
  var thrSteps = Math.max(1, Math.round(thrH / 0.25))
  // pursuit prediction (threatTurnRate rad/s > 0 = on): a fast tracked body is assumed to HOME on the car (pure pursuit of the
  // car's pose on the candidate path + threatLead s of its motion, speed kept, heading change limited to threatTurnRate). Per step the
  // nearer of the constant-velocity and the pursuit prediction counts. Without it a pursuer aimed at the car reads as a straight line
  // that misses, and the gap between two converging pursuers looks free.
  var thrTurn = params.threatTurnRate != null ? params.threatTurnRate : 0
  var thrLead = params.threatLead != null ? params.threatLead : 0.3
  // threatTurnMin (rad/s, 0 = off): the pursuit prediction uses the body's OBSERVED turn rate (av.threats[].turn, x1.3 + 0.15), clamped to [threatTurnMin, threatTurnRate]
  var thrTurnMin = params.threatTurnMin != null ? params.threatTurnMin : 0
  var thrHit = params.threatHit != null ? params.threatHit : 3
  // threatHitFloor (cost units, default 0): extra flat penalty of ANY predicted contact. Progress toward the goal is worth ~1 per metre over a 100+ m horizon, so a candidate that
  // reaches the goal but is predicted to hit used to beat the straight run with no hit (corner-trap: the 'aim at the carrot' arc into a pursuer won by 115 m of progress).
  var thrHitFloor = params.threatHitFloor != null ? params.threatHitFloor : 0
  var thrMinPursuit = params.threatPursuitSpeed != null ? params.threatPursuitSpeed : 4
  var vEff = Math.max(v, 5)
  // distance travelled after t s along a candidate for the threat prediction: the car is assumed to keep accelerating (threatAccel m/s^2, 0 = constant speed)
  // up to the cruise speed (a car that is about to launch / is accelerating covers more ground than its current speed says)
  var thrAcc = params.threatAccel != null ? params.threatAccel : 0
  var vTop = Math.max(vEff, params.cruiseSpeed != null ? params.cruiseSpeed : 10)
  var aLatThr = params.maxLatAccel || 9
  var vCurveMin = params.minSpeed != null ? params.minSpeed : 4
  var sKappa = 0
  var sVt = vEff
  // speed profile along the candidate with curvature kappa: towards min(cruise, curve limit sqrt(aLat / |kappa|)) at threatAccel (up) / comfortDecel (down);
  // a hard dodge is slow (and therefore tight), a straight run keeps accelerating
  function setProfile(kappa) {
    sKappa = kappa
    var vt = vTop
    var ak = Math.abs(kappa)
    if (ak > 1e-3) vt = Math.min(vt, Math.max(vCurveMin, Math.sqrt(aLatThr / ak)))
    if (thrAcc <= 0 && vt > vEff) vt = vEff
    sVt = vt
  }
  function sAt(t) {
    if (thrAcc <= 0 && sVt >= vEff) return vEff * t
    var dv = sVt - vEff
    var acc = dv >= 0 ? thrAcc : aBrake
    if (acc <= 0) return vEff * t
    var t1 = Math.abs(dv) / acc
    var sg = dv >= 0 ? 1 : -1
    if (t <= t1) return vEff * t + 0.5 * sg * acc * t * t
    return vEff * t1 + 0.5 * sg * acc * t1 * t1 + sVt * (t - t1)
  }
  // Points on a FAST tracked body (threatPursuitSpeed) are not static obstacles: it is predicted (threatCost), and its current position
  // smeared into the costmap reads as a wall that it has long left (a chaser alongside blocked every path -> full stop in front of it).
  var moverR = params.threatBodyRadius != null ? params.threatBodyRadius : 0
  if (moverR > 0 && thr.length) {
    var fx = []
    var fy = []
    for (var oi = 0; oi < ox.length; oi++) {
      var skip = false
      for (var mi = 0; mi < thr.length; mi++) {
        if (thr[mi].sp > thrMinPursuit) {
          var mx = ox[oi] - thr[mi].x
          var my = oy[oi] - thr[mi].y
          if (mx * mx + my * my < moverR * moverR) skip = true
        }
      }
      if (!skip) {
        fx.push(ox[oi])
        fy.push(oy[oi])
      }
    }
    ox = fx
    oy = fy
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }
  // Predicted proximity of the car (hull at the pose reached at time t along the path) to each tracked body (constant velocity):
  // sum over time of the relative penetration of the gap band, earlier = heavier; an actual overlap counts double.
  var PQ = []
  function threatCost(kappa, turnLen, hullLx, hullWx) {
    var tc = 0
    var hit = 0
    setProfile(kappa)
    var pursue = thrTurn > 0
    if (pursue) {
      for (var pi = 0; pi < thr.length; pi++) {
        var q0 = thr[pi]
        PQ[pi] = { x: q0.x, y: q0.y, h: q0.h }
      }
    }
    var sub = 2
    var tprev = 0
    for (var si = 1; si <= thrSteps; si++) {
      var t = si * 0.25
      var sPath = sAt(t)
      poseAt(kappa, turnLen, sPath, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      var wt = 1 - (0.6 * (si - 1)) / thrSteps
      for (var qi = 0; qi < thr.length; qi++) {
        var q = thr[qi]
        var rx = q.x + q.vx * t - P.x
        var ry = q.y + q.vy * t - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        var ex = Math.max(Math.abs(lx) - hullLx, 0)
        var ey = Math.max(Math.abs(ly) - hullWx, 0)
        var d = Math.sqrt(ex * ex + ey * ey) - thrR
        if (pursue && q.sp > thrMinPursuit) {
          var c = PQ[qi]
          var tgx = P.x + (sAt(t + thrLead) - sPath) * ct
          var tgy = P.y + (sAt(t + thrLead) - sPath) * st
          var sdt = (t - tprev) / sub
          for (var ss = 0; ss < sub; ss++) {
            var dh = Math.atan2(tgy - c.y, tgx - c.x) - c.h
            while (dh > Math.PI) dh -= 2 * Math.PI
            while (dh < -Math.PI) dh += 2 * Math.PI
            var lim = (q.turn != null && thrTurnMin > 0 ? Math.min(thrTurn, Math.max(thrTurnMin, 1.3 * q.turn + 0.15)) : thrTurn) * sdt
            c.h += dh > lim ? lim : dh < -lim ? -lim : dh
            c.x += Math.cos(c.h) * q.sp * sdt
            c.y += Math.sin(c.h) * q.sp * sdt
          }
          var prx = c.x - P.x
          var pry = c.y - P.y
          var plx = ct * prx + st * pry
          var ply = -st * prx + ct * pry
          var pex = Math.max(Math.abs(plx) - hullLx, 0)
          var pey = Math.max(Math.abs(ply) - hullWx, 0)
          var pd = Math.sqrt(pex * pex + pey * pey) - thrR
          if (pd < d) d = pd
        }
        if (d < thrGap) tc += wt * (d < 0 ? 2 : 0) + (wt * (thrGap - Math.max(d, 0))) / thrGap
        // predicted contact: one penalty by the EARLIEST hit (a later hit can still be dodged by re-planning), not diluted by the horizon average
        if (d < 0 && hit === 0) hit = 1 - (0.5 * (si - 1)) / thrSteps
      }
      tprev = t
    }
    return tc / thrSteps + thrHit * hit + (hit > 0 ? thrHitFloor / wThreat : 0)
  }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  // Start already inside the margin (parked next to a car / wall): the full margin would veto every path at s = 0 and
  // freeze the car. The margin therefore starts at the clearance the car has now and grows to the full value over
  // `marginRamp` metres — a path may not get closer than the car already is, but it may drive away.
  var hullL = halfL - margin
  var hullW = halfW - margin
  var startGap = margin + soft
  for (var sg = 0; sg < ox.length; sg++) {
    if (ox[sg] < -hullL + rearIgnore - margin) continue
    var gap = Math.max(Math.abs(ox[sg]) - hullL, Math.abs(oy[sg]) - hullW)
    if (gap < startGap) startGap = gap
  }
  var ramp = params.marginRamp != null ? params.marginRamp : 3
  // 8 m spatial hash over the ego-frame costmap: only points near the swept pose can hit its rectangle
  var HC = 8
  var hash = new Map()
  for (var hi = 0; hi < ox.length; hi++) {
    var hk = (Math.floor(ox[hi] / HC) + 512) * 1024 + (Math.floor(oy[hi] / HC) + 512)
    var hcell = hash.get(hk)
    if (hcell) hcell.push(hi)
    else hash.set(hk, [hi])
  }
  function freeLength(kappa, turnLen, hw, hl) {
    var extra = hw - hullW
    var m0 = Math.max(0, Math.min(extra, startGap - 0.05))
    for (var s = 0; s <= H; s += ds) {
      var m = s >= ramp || m0 >= extra ? extra : m0 + ((extra - m0) * s) / ramp
      var hwS = hullW + m
      var hlS = hullL + m
      var hlRear = Math.max(0.3, hlS - rearIgnore)
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      var hlMax = hlS > hlRear ? hlS : hlRear
      var rad = Math.sqrt(hlMax * hlMax + hwS * hwS) + 1e-6
      var cx0 = Math.floor((P.x - rad) / HC)
      var cx1 = Math.floor((P.x + rad) / HC)
      var cy0 = Math.floor((P.y - rad) / HC)
      var cy1 = Math.floor((P.y + rad) / HC)
      for (var cx = cx0; cx <= cx1; cx++) {
        for (var cy = cy0; cy <= cy1; cy++) {
          var cell = hash.get((cx + 512) * 1024 + (cy + 512))
          if (!cell) continue
          for (var qi = 0; qi < cell.length; qi++) {
            var q = cell[qi]
            var rx = ox[q] - P.x
            var ry = oy[q] - P.y
            var lx = ct * rx + st * ry
            var ly = -st * rx + ct * ry
            if (lx > -hlRear && lx < hlS && ly > -hwS && ly < hwS) return Math.max(0, s - ds)
          }
        }
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var bestKey = -1
  var prevKey = state.prevKey != null ? state.prevKey : -1
  var prevHit = null
  var cand = []
  // Direct aim: turn at curvature `kappa` until the car points at the goal, then drive straight (shortest way when the
  // way is free). Returns the turn angle (rad), or 0 when the goal is on the other side / cannot be aimed at this way.
  function aimTurnAngle(kappa) {
    var ak = Math.abs(kappa)
    if (ak < 1e-6) return 0
    var gyS = kappa > 0 ? gy : -gy
    if (gyS <= 0.05 && gx > 0) return 0
    var prevF = null
    for (var th = 0.02; th <= Math.PI; th += 0.02) {
      var x = Math.sin(th) / ak
      var y = (1 - Math.cos(th)) / ak
      var f = Math.atan2(gyS - y, gx - x) - th
      while (f > Math.PI) f -= 2 * Math.PI
      while (f < -Math.PI) f += 2 * Math.PI
      if (prevF !== null && prevF > 0 && f <= 0) return th
      prevF = f
    }
    return 0
  }
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    var aimAng = aimTurnAngle(kappa)
    var nAngles = turnAngles.length + (aimAng > 0 ? 1 : 0)
    for (var ti = 0; ti < nAngles; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var isAim = ti >= turnAngles.length
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, (isAim ? aimAng : turnAngles[ti]) / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      var Lpose = L
      if (isAim) {
        // judged where it reaches the goal (not far beyond it); free-length terms still use the full free path
        poseAt(kappa, turnLen, turnLen, P)
        Lpose = Math.min(L, turnLen + Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y)))
      }
      poseAt(kappa, turnLen, Lpose, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (thr.length) cost += wThreat * threatCost(kappa, turnLen, hullL, hullW)
      var key = a * 4 + ti
      if (key === prevKey) prevHit = { cost: cost, kappa: kappa, hard: fHard, soft: fSoft, turnLen: turnLen }
      if (cost < bestCost) {
        bestKey = key
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  // plan-switch hysteresis (switchMargin, cost units, 0 = off): keep last frame's candidate (same curvature index / turn
  // segment) unless another one is cheaper by the margin. Stops the chosen path flipping between near-equal candidates.
  var switchMargin = params.switchMargin != null ? params.switchMargin : 0
  if (switchMargin > 0 && prevHit && bestKey !== prevKey && bestCost > prevHit.cost - switchMargin && prevHit.hard >= minFree) {
    bestKey = prevKey
    bestCost = prevHit.cost
    best = prevHit.kappa
    bestHard = prevHit.hard
    bestSoft = prevHit.soft
    bestTurnLen = prevHit.turnLen
  }
  state.prevKappa = best
  state.prevKey = bestKey

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    startGap: startGap,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

av_speed_planner.code:
// AV stack · PLAN / speed planner.
// v_des = min(cruise, obstacle in the path (auto-brake), obstacle right next to the car, route bends ahead, lateral acceleration, goal approach).
//  - In the path: auto-brake logic — v <= sqrt(2 * brakeDecel * (free distance - stopMargin)). Far obstacles only matter once they are within braking distance.
//  - Next to the car: only obstacles within `obstacleSlowRadius` (default 5 m) of the hull slow the car, linearly from `obstacleSlowFactor * cruiseSpeed` (touching) up to cruise (at the radius).
//    Obstacles that are farther away, or behind the car, never slow it. Set the radius to 0 to switch this off.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// The free-path (stopping distance) limit always wins over the floors.
// Publishes av.plan.vDesired / av.plan.vLimit ('cruise' | 'free' | 'near' | 'route' | 'curve' | 'goal').
// params: cruiseSpeed, minSpeed (lowest speed while driving, default 4), comfortDecel (brake decel for obstacles in the path, default 5),
//         stopMargin, obstacleSlowRadius (5), obstacleSlowFactor (speed right next to an obstacle as a fraction of cruise, default 0.5), maxLatAccel (default 9), curveSmooth (s, 0 = raw kappa), curveDeadband (1/m, 0 = off),
//         chasedDecel (0 = off; free-path braking decel while a fast body closes in), goalDecel (gentler braking used for the final approach, default 3), goalCrawlSpeed (floor while arriving, default 2), goalTolerance, vehicleWidth, vehicleLength, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 9
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.minSpeed != null ? params.minSpeed : params.crawlSpeed != null ? params.crawlSpeed : 4
  var limit = 'cruise'
  var v = cruise
  // Chased = a fast body closes in on the car. While chased: (1) braking for a bend of the (stale) route in front of a 30 m/s pursuer lets it catch up
  // (corner-trap: 32 -> 11 m/s on the route limit, caught 2 s later): no route limit (the planned path's own curve limit below still applies); (2) the free-path
  // stopping limit uses `chasedDecel` (the car's emergency braking) instead of the comfort decel (a 35 m free path toward a far wall capped the car at 16 m/s with a 25 m/s pursuer behind).
  var chased = false
  if (av.threats && av.threats.length) {
    for (var ti = 0; ti < av.threats.length; ti++) {
      var th = av.threats[ti]
      var tx = th.x - input.position[0]
      var tz = th.z - input.position[2]
      var tsp = Math.sqrt(th.vx * th.vx + th.vz * th.vz)
      if (tsp > 4 && tx * tx + tz * tz < 90 * 90 && th.vx * tx + th.vz * tz < 0) chased = true
    }
  }
  // obstacle in the path: auto-brake (free distance of the chosen path)
  var aFree = chased && params.chasedDecel > aBrake ? params.chasedDecel : aBrake
  var vFree = Math.sqrt(2 * aFree * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // obstacles right next to the car (hull distance), never farther than the slow radius, never behind
  var slowR = params.obstacleSlowRadius != null ? params.obstacleSlowRadius : 5
  if (slowR > 0 && av.points && av.points.length && av.ego) {
    var e = av.ego
    var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2
    var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    var pos = input.position
    var dn = Infinity
    for (var i = 0; i < av.points.length; i++) {
      var dx = av.points[i][0] - pos[0]
      var dz = av.points[i][1] - pos[2]
      var lx = dx * e.fwd[0] + dz * e.fwd[2]
      if (lx < -hl) continue // behind the rear: irrelevant for a forward-driving car
      var ly = dx * e.left[0] + dz * e.left[2]
      var ex = Math.max(Math.abs(lx) - hl, 0)
      var ey = Math.max(Math.abs(ly) - hw, 0)
      var d = Math.sqrt(ex * ex + ey * ey)
      if (d < dn) dn = d
    }
    if (dn < slowR) {
      var vNear = Math.max(crawl, (params.obstacleSlowFactor != null ? params.obstacleSlowFactor : 0.5) * cruise)
      var t = Math.min(1, Math.max(0, (dn - 0.3) / Math.max(0.01, slowR - 0.3)))
      var vProx = vNear + (cruise - vNear) * t
      if (vProx < v) {
        v = vProx
        limit = 'near'
      }
    }
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v && !chased) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  // Curve limit from the NET path curvature: signed kappa smoothed over `curveSmooth` s (default 0 = raw) cancels the
  // left/right wobble of the discrete candidate curvatures on a straight; |k| below `curveDeadband` (1/m) is ignored.
  var kRaw = plan.kappa
  var tau = params.curveSmooth != null ? params.curveSmooth : 0
  if (tau > 0) {
    var al = Math.min(1, (dt || 0.016) / tau)
    state.ks = (state.ks || 0) + al * (kRaw - (state.ks || 0))
    kRaw = state.ks
  }
  var k = Math.abs(kRaw)
  if (k < (params.curveDeadband || 0)) k = 0
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = Math.max(vCurve, crawl)
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * (params.goalDecel != null ? params.goalDecel : 3) * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        // arriving: creep in slowly enough to stop inside the hold radius (own, lower floor than the driving minimum)
        v = Math.max(vGoal, params.goalCrawlSpeed != null ? params.goalCrawlSpeed : 2)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl && limit !== 'goal') v = crawl
  // The stopping-distance limit is a safety bound, not a preference: no floor (minSpeed, route/curve crawl, goal crawl)
  // may lift the speed above what can still stop within the free path (minSpeed 9.4 with 5 m free and 2 m/s² used to
  // drive at 9.4 instead of 3.9 m/s — straight into the AEB, then stop-and-go).
  if (v > vFree) {
    v = vFree
    limit = 'free'
  }
  plan.vDesired = v
  plan.vLimit = limit
  state.lim = limit
  state.vd = v
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

av_supervisor.code:
// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

av_control_lateral.code:
// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate, kappaTau (0.04 s + 0.008 s per m/s), kappaJump (0.025 1/m)
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kRaw = av.plan.kappa
  // Smoothing: the planner picks one of a few dozen discrete curvatures every frame, so a tiny change of goal / costmap hops
  // between neighbours (visible as fast left-right steering). Small changes (< kappaJump) are low-passed
  // (tau 0.04 s + 0.008 s per m/s); a large change (avoidance) passes through quickly (tau 0.04 s). Reverse / manoeuvre override bypass the filter (precise geometry).
  var v = Math.abs(e.speed)
  if (state.kf === undefined || av.mode === 'reverse' || av.plan.override || v < 2) state.kf = kRaw
  var jump = Math.abs(kRaw - state.kf)
  var tauK = jump > (params.kappaJump != null ? params.kappaJump : 0.025) ? 0.04 : (params.kappaTau != null ? params.kappaTau : 0.04) + 0.008 * v
  state.kf += (kRaw - state.kf) * Math.min(1, dt / (tauK + dt))
  var kCmd = state.kf
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

av_control_longitudinal.code:
// AV stack · CONTROL / longitudinal (model-based speed control with an online-identified actuator model).
// The car2 actuator turns a command u = throttle − brake into a force, so the body follows
//     a = G · u − D · sgn(v)          (G: m/s² per unit command, D: sliding/rolling friction deceleration, m/s²)
// G and D differ by orders of magnitude between bodies (reference car: G ≈ 156, D ≈ 60; a light icy car with power 2400:
// G ≈ 1200, D ≈ 1). A fixed deadband / gain only fits one of them — on the other the smallest command jumps the speed by
// metres per second per frame and the controller bang-bangs (the "jitter"). So G and D are estimated online (D from coasting
// frames, G from commanded frames with D fixed; the previous frame's command vs. the measured acceleration) and the controller asks for an
// acceleration: u = (a_des + D · s) / G, a_des = clamp((v_target − v) / tau + I, −maxDecel, maxAccel).
// Publishes av.actuator {G, D, u} (u = applied command; a later stage that overrides the actions must update it — the AEB does). The AEB uses it to brake with a deceleration instead of a raw command) and av.cmd.
// At rest the static friction can exceed D: a breakaway offset ramps while demanded motion does not start.
// params: tau, ki, maxAccel, maxDecel, maxThrottle, maxBrake, breakawayRate, gainInit, frictionInit
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var tau = params.tau != null ? params.tau : 0.35
  var ki = params.ki != null ? params.ki : 0.6
  var maxAcc = params.maxAccel != null ? params.maxAccel : 10
  var maxDec = params.maxDecel != null ? params.maxDecel : 12
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 1
  var maxBrk = params.maxBrake != null ? params.maxBrake : 1
  var v = e.speed
  if (state.G === undefined) {
    state.G = params.gainInit != null ? params.gainInit : 156
    state.D = params.frictionInit != null ? params.frictionInit : 60
    state.uPrev = 0
    state.vPrev = v
    state.I = 0
    state.boost = 0
    state.samples = 0
  }
  // --- identify: last frame's command produced this frame's acceleration ---
  // a later stage (AEB) that overrode the command reports what was really applied in last frame's av.actuator.u
  if (state.lastAct && typeof state.lastAct.u === 'number') state.uPrev = state.lastAct.u
  var aMeas = dt > 1e-6 ? (v - state.vPrev) / dt : 0
  var vMid = 0.5 * (v + state.vPrev)
  var pushing = input.environment && input.environment.isTouchingSide
  // (sliding friction acts as soon as the body slides: learn from 0.12 m/s on, so a car creeping in force balance is not
  // stuck between 'too slow to learn' and 'too fast for the breakaway push')
  // G and D are identified SEPARATELY (the former joint RLS on [G, D] was ill-conditioned: with the speed in one direction the data only fix
  // G * u - D, so an underestimated G was 'explained' by a runaway D (0 -> 300 within 20 frames), and the controller then commanded forward
  // thrust against its own friction model: speed kicks and 60+ m/s runaways on light powerful cars):
  //  - D from COASTING frames (command ~ 0, moving): the deceleration is the friction, a = -D * sgn(v), directly;
  //  - G from COMMANDED frames with D fixed: normalised LMS on a = G * u - D * sgn(v), weighted by the command (a tiny command says little).
  if (!pushing && Math.abs(vMid) > 0.12 && state.vPrev * v > 0) {
    var sgnV = vMid > 0 ? 1 : -1
    if (Math.abs(state.uPrev) > 1e-4) {
      var x0 = state.uPrev
      var err = aMeas - (state.G * x0 - state.D * sgnV)
      // robust: a collision / kerb spike must not wreck the model
      var lim = 50 + 0.5 * Math.abs(state.G * x0)
      if (err > lim) err = lim
      if (err < -lim) err = -lim
      var dG = (0.5 * err * x0) / (x0 * x0 + 4e-4)
      // one noisy sample must not drop G to the floor (next frame u = 1.0 with the real G = 1200: +20 m/s in two frames).
      // Growth is safe (a larger G means a smaller command) and may be fast: a car whose real G is 9x the prior needs ~7 frames.
      var capG = 0.1 * state.G + 2
      var capGUp = 0.35 * state.G + 2
      if (dG > capGUp) dG = capGUp
      if (dG < -capG) dG = -capG
      state.G = Math.max(10, Math.min(20000, state.G + dG))
      state.samples++
    } else if (Math.abs(v) > 1) {
      var dMeas = -aMeas * sgnV
      if (dMeas < 0) dMeas = 0
      if (dMeas > 300) dMeas = 300
      state.D += 0.15 * (dMeas - state.D)
      state.samples++
    }
  }
  // Rescue path: the command clearly dominates friction and the response is far larger than the model predicts
  // (G underestimated — e.g. learned while pushing against a slope, or while the speed sign flipped every frame, where
  // the RLS is gated off). Pull G towards the observed gain directly so the controller stops saturating.
  // Only for a saturated command (that is the failure mode); collisions also produce big accelerations and must not pump G.
  if (!pushing && Math.abs(state.uPrev) > 0.3 && aMeas * state.uPrev > 0 && Math.abs(aMeas) > 3 * state.D + 10) {
    var gObs = Math.abs(aMeas / state.uPrev)
    if (gObs > 1.5 * state.G) state.G = Math.min(20000, state.G + 0.3 * (gObs - state.G))
  }
  var G = state.G
  var D = state.D

  // --- control ---
  var u = 0
  var holding = Math.abs(vDes) < 0.05 && Math.abs(v) < 0.3
  if (holding) {
    state.I = 0
    state.boost = 0
  } else {
    var errV = vDes - v
    // integral (acceleration units) only while not saturated, so steady errors (slope, model error) vanish
    var aDes = errV / tau + state.I
    if (aDes > maxAcc) aDes = maxAcc
    if (aDes < -maxDec) aDes = -maxDec
    if (aDes > -maxDec && aDes < maxAcc) state.I = Math.max(-3, Math.min(3, state.I + ki * errV * dt))
    // never brake through zero within one frame: the deceleration that stops the car this frame is the most we ask for
    if (Math.abs(vDes) < 0.05) {
      var stopA = Math.abs(v) / Math.max(dt, 1e-3)
      if (v > 0 && aDes < -stopA) aDes = -stopA
      if (v < 0 && aDes > stopA) aDes = stopA
    }
    // friction feed-forward in the direction of travel (at rest: of the wanted motion)
    var s = Math.abs(v) > 0.3 ? (v > 0 ? 1 : -1) : aDes > 0 ? 1 : aDes < 0 ? -1 : 0
    var fric = D * s
    // at rest, friction helps braking: no reverse push needed to stay stopped
    if (Math.abs(v) <= 0.3 && Math.abs(vDes) < 0.05) fric = 0
    u = (aDes + fric) / G
    // (A probe cap on the first command was tried against the one-frame standing-start kick: it delayed every launch by ~1.5 s, so an
    // evasion from rest started late and the planner's threatAccel speed profile over-promised -> pincer / crossing / corner-trap contacts. Removed.)
    // breakaway: demanded motion does not start (static friction > D) -> ramp an extra push
    var want = Math.abs(vDes) > 0.3
    // far below the demanded speed and not gaining (static friction / force balance the model does not explain yet)
    // 'driving' = clearly moving in the demanded direction (a creep of 0.1 m/s that comes and goes must not count: the push relaxed
    // at every creep and the car idled for ever at a boost just below breakaway, G / D of the model nonsense)
    var driveThr = Math.max(0.5, Math.min(1.5, 0.25 * Math.abs(vDes)))
    var drive = vDes > 0 ? v : -v
    var stuck = want && drive < driveThr && vDes * aDes > 0 && aMeas * (vDes > 0 ? 1 : -1) < 0.5
    if (stuck) state.boost = Math.min(1, state.boost + (params.breakawayRate != null ? params.breakawayRate : 0.5) * dt)
    // keep the push until the car really drives (else it jerks, stops, ramps again); then relax it slowly
    else if (!want || drive >= driveThr) state.boost = Math.max(0, state.boost - 0.5 * dt)
    if (state.boost > 0 && want) u += (vDes > 0 ? 1 : -1) * state.boost
    // overspeed (much faster than demanded (> 8 m/s), in the direction of travel, and still accelerating): never push along the direction of travel either. A friction feed-forward
    // (aDes + D) / G with an overestimated D asked for forward thrust while braking, i.e. the car accelerated to 60+ m/s against a demand of 10;
    // friction / brake alone slow it down, and the model catches up.
    var sTrav = v > 0 ? 1 : -1
    if (Math.abs(v) > 1 && (v - vDes) * sTrav > 8 && u * sTrav > 0 && aMeas * sTrav > 0) u = 0
    // stopping: never push along the direction of travel (friction alone may decelerate harder than maxDecel — fine)
    if (Math.abs(vDes) < 0.05 && u * v > 0) u = 0
  }
  if (u > maxThr) u = maxThr
  if (u < -maxBrk) u = -maxBrk
  state.uPrev = u
  state.vPrev = v
  input.actions.throttle = u > 0 ? u : 0
  input.actions.brake = u < 0 ? -u : 0
  // mailbox: stages after this one write the command they actually applied into av.actuator.u
  av.actuator = { G: G, D: D, samples: state.samples, u: u }
  state.lastAct = av.actuator
  av.cmd = { throttle: input.actions.throttle, brake: input.actions.brake }
  api.watch('av.throttle', 'u ' + u.toFixed(3) + ' G ' + G.toFixed(0) + ' D ' + D.toFixed(1) + ' vd ' + vDes.toFixed(1))
  return {}
}

av_aeb.code:
// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// Brakes with a deceleration (aebDecel), turned into a command with the actuator model the longitudinal stage identified
// (av.actuator {G, D}): a raw brake value means 360 m/s² on a light, powerful car and flips its speed within a frame.
// Footprint from av.vehicle (look-ahead starts at the nose, spread covers the body width).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var len = (av.vehicle && av.vehicle.length) || params.vehicleLength || 4
  var wid = (av.vehicle && av.vehicle.width) || params.vehicleWidth || 2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : Math.max(0.9, wid / 2 - 0.1)
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, len / 2 + 0.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    // deceleration needed to stop before the hit (at least aebDecel), never more than stops the car within this frame
    var room = Math.max(0.1, hit.distance - 0.2 * margin)
    var dec = Math.max(a, (e.speed * e.speed) / (2 * room))
    dec = Math.min(dec, e.speed / Math.max(dt, 1e-3))
    var act = av.actuator
    var u
    if (act && act.G > 0) u = (-dec + act.D) / act.G
    else u = -Math.min(1, 0.3 + (need - hit.distance) / need)
    var cur = (input.actions.throttle || 0) - (input.actions.brake || 0)
    if (u < cur) {
      input.actions.throttle = u > 0 ? u : 0
      input.actions.brake = u < 0 ? Math.min(1, -u) : 0
      // tell the longitudinal controller what was really applied (its actuator identification)
      if (act) act.u = input.actions.throttle - input.actions.brake
    }
    api.watch('av.aeb', Math.round(hit.distance * 10) / 10 + ' m dec ' + dec.toFixed(1))
  }
  return {}
}
